```c
/* k07_nbody: all-pairs gravitational acceleration, one step.
 * UNIFORM cost per body (each body visits all n others), compute-bound. */
#include <math.h>
#include <omp.h>
#include "common.h"

/* === KERNEL BEGIN === */
static void kernel(int n, const double *px, const double *py, const double *pz,
                   const double *m, double *ax, double *ay, double *az) {
    /* 
     * Parallelize the outer loop. Since the target machine (Apple M4) has 
     * heterogeneous cores (P-cores and E-cores), a 'guided' schedule is 
     * used to ensure that faster cores handle more work, preventing 
     * load imbalance that would occur with a 'static' schedule.
     */
    #pragma omp parallel for schedule(guided)
    for (int i = 0; i < n; i++) {
        /* Hoist constant values for the inner loop to reduce memory loads */
        const double xi = px[i];
        const double yi = py[i];
        const double zi = pz[i];
        double sx = 0.0, sy = 0.0, sz = 0.0;

        for (int j = 0; j < n; j++) {
            const double dx = px[j] - xi;
            const double dy = py[j] - yi;
            const double dz = pz[j] - zi;

            /* Compute softened distance squared */
            const double r2 = dx * dx + dy * dy + dz * dz + 1e-9;

            /* 
             * Compute 1/r^3 and scale by mass. 
             * Using r2 * sqrt(r2) is equivalent to r^3.
             */
            const double inv = m[j] / (r2 * sqrt(r2));

            sx += dx * inv;
            sy += dy * inv;
            sz += dz * inv;
        }
        ax[i] = sx;
        ay[i] = sy;
        az[i] = sz;
    }
}
/* === KERNEL END === */

int main(int argc, char **argv) {
    int n = (int)arg_long(argc, argv, 1, 12000);
    double *b = xmalloc(7L * n * sizeof *b);
    double *px = b, *py = b + n, *pz = b + 2L * n, *m = b + 3L * n;
    double *ax = b + 4L * n, *ay = b + 5L * n, *az = b + 6L * n;
    rng_seed(7);
    for (int i = 0; i < n; i++) { px[i] = rng_unit(); py[i] = rng_unit(); pz[i] = rng_unit(); m[i] = rng_unit(); }

    double t0 = now_sec();
    kernel(n, px, py, pz, m, ax, ay, az);
    double t1 = now_sec();

    double sum = 0.0;
    for (int i = 0; i < n; i++) sum += fabs(ax[i]) + fabs(ay[i]) + fabs(az[i]);
    report("nbody", t1 - t0, sum);
    free(b);
    return 0;
}

